import sys

def solve():
    try:
        input_data = sys.stdin.read().strip()
        if not input_data:
            return
        X = int(input_data)
    except ValueError:
        return

    total_sum = 0
    # Iterate through rows 1 to 9
    for i in range(1, 10):
        # Iterate through columns 1 to 9
        for j in range(1, 10):
            val = i * j
            if val != X:
                total_sum += val

    print(total_sum)

if __name__ == '__main__':
    solve()

